const zlib = require('zlib');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { pipeline } = require('stream/promises');
const { Transform } = require('stream');

const AUDIT_LOG = path.join('/var/log/ci', 'artifact-audit.log');
const ARTIFACT_DIR = path.join('/tmp/ci-artifacts');
const MAX_COMPRESSED_SIZE = 50 * 1024 * 1024; // 50MB compressed limit
const DECOMPRESSION_RATIO_LIMIT = 100; // ratio limit

class ArtifactProcessor {
  constructor(jobId, userId) {
    this.jobId = jobId;
    this.userId = userId;
    this.bytesRead = 0;
    this.bytesWritten = 0;
    this.startTime = Date.now();
  }

  async auditLog(action, details) {
    const entry = {
      timestamp: new Date().toISOString(),
      jobId: this.jobId,
      userId: this.userId,
      action,
      details,
      bytesProcessed: this.bytesWritten
    };
    await fs.promises.appendFile(AUDIT_LOG, JSON.stringify(entry) + '\n');
  }

  createRatioMonitor() {
    const self = this;
    return new Transform({
      transform(chunk, encoding, callback) {
        self.bytesWritten += chunk.length;
        // Check ratio periodically to avoid overhead on every chunk
        if (self.bytesWritten % (1024 * 1024) < chunk.length) {
          const currentRatio = self.bytesRead > 0 
            ? self.bytesWritten / self.bytesRead 
            : 0;
          if (currentRatio > DECOMPRESSION_RATIO_LIMIT) {
            callback(new Error(`Decompression ratio ${currentRatio.toFixed(1)} exceeds limit`));
            return;
          }
        }
        callback(null, chunk);
      }
    });
  }

  validateCompressedSize(filePath) {
    const stats = fs.statSync(filePath);
    if (stats.size > MAX_COMPRESSED_SIZE) {
      throw new Error(`Compressed file size ${stats.size} exceeds limit ${MAX_COMPRESSED_SIZE}`);
    }
    this.bytesRead = stats.size;
    return stats.size;
  }

  computeChecksum(filePath) {
    return new Promise((resolve, reject) => {
      const hash = crypto.createHash('sha256');
      const stream = fs.createReadStream(filePath);
      stream.on('data', (d) => hash.update(d));
      stream.on('end', () => resolve(hash.digest('hex')));
      stream.on('error', reject);
    });
  }

  async processArtifact(compressedFilePath) {
    const safeName = path.basename(compressedFilePath).replace(/[^a-zA-Z0-9._-]/g, '_');
    const outputPath = path.join(ARTIFACT_DIR, this.jobId, safeName + '.out');

    await fs.promises.mkdir(path.dirname(outputPath), { recursive: true });

    await this.auditLog('PROCESS_START', { file: safeName });

    try {
      this.validateCompressedSize(compressedFilePath);
      const checksum = await this.computeChecksum(compressedFilePath);

      await this.auditLog('CHECKSUM_VERIFIED', { sha256: checksum });

      const readStream = fs.createReadStream(compressedFilePath);
      const gunzip = zlib.createGunzip();
      const ratioMonitor = this.createRatioMonitor();
      const writeStream = fs.createWriteStream(outputPath);

      await pipeline(readStream, gunzip, ratioMonitor, writeStream);

      await this.auditLog('PROCESS_COMPLETE', {
        outputSize: this.bytesWritten,
        ratio: (this.bytesWritten / this.bytesRead).toFixed(2),
        duration: Date.now() - this.startTime
      });

      return { success: true, outputPath, size: this.bytesWritten };
    } catch (err) {
      await this.auditLog('PROCESS_FAILED', { error: err.message });
      // Cleanup partial output
      try { await fs.promises.unlink(outputPath); } catch (_) {}
      throw err;
    }
  }
}

async function handleCIArtifactUpload(req) {
  const { jobId, userId, artifactPath } = req;

  if (!jobId || !userId || !artifactPath) {
    throw new Error('Missing required fields');
  }

  const resolvedPath = path.resolve(artifactPath);
  if (!resolvedPath.startsWith('/tmp/ci-uploads/')) {
    throw new Error('Invalid artifact path');
  }

  const processor = new ArtifactProcessor(jobId, userId);
  return processor.processArtifact(resolvedPath);
}

module.exports = { ArtifactProcessor, handleCIArtifactUpload };
